      "card_ids": ["C22"],
      "claim": "Naltrexone oral bioavailability is ~5% in healthy volunteers, but its low F is due to extensive first-pass metabolism of the cyclopropylmethyl/ketone motif, absent in galantamine.",
      "evidence_role": "contradictory"
    }
